md += ['', f'## B · Abnahmen aus Projektdateien ({len(imp)})', '', '| Datei:Zeile | Teil | Georg |', '| --- | --- | --- |']
md += [f"| `{r['source']}` | {r['part']} | {r['georg']} |" for r in imp]
open(os.path.join(H, 'DECISIONS.md'), 'w', encoding='utf-8').write('\n'.join(md) + '\n')
